<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>My Joke Website</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            background-color: #f4faff;
            margin: 0;
            padding: 20px;
        }
        h1 {
            color: #33ccff;
            border-bottom: 2px solid #333;
            margin-bottom: 20px;
        }
        .joke {
            background-color: #fff;
            padding: 15px;
            border-radius: 5px;
            box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
            width: 60%; /* Adjust width as needed */
            max-width: 800px; /* This ensures it never exceeds specific pixels for better responsiveness */
            margin: 20px auto;
            text-align: center;
        }
        .joke p {
            font-size: 1.1em;
            margin: 0;
        }
        @keyframes revealAnimation {
            from { opacity: 0; }
            to { opacity: 1; }
        }
        .hidden-content {
            justify-content: flex-start;
            margin-top: 2em;
        }
        @media (max-width: 480px) {
            .joke {
                width: 80%;
            }
        }
    </style>
</head>
